// BeInTheRoom, live mode.
//
// A scenario played as a story the student is inside, one beat at a time:
// people speak to them, documents land on the counter, a choice is made without
// knowing its cost, and the room answers. Three gauges and a "who counts"
// tracker carry the consequences from scene to scene, the run ends on one of
// several endings, the real record follows, and one written reflection reaches
// Canvas.
//
// HOW IT WORKS. The scenario (window.BH_LIVE_ROOM, generated by
// scripts/build-live-rooms.js from scripts/lib/live-rooms/) is data only. On
// every change this file rebuilds one flat list of items, the timeline, from
// the scenario plus what the student has done so far, and shows the first
// `cursor` of them. Three kinds of item block the timeline until answered: a
// document question, an in-character reply, and a choice. Nothing else here
// holds state, so a refresh puts the student exactly where they were.
//
// THE CAPTURE KEY IS WRITTEN FROM ONE PLACE: the reflection box's input event.
// Playing again, tapping a choice or reloading the page must never be able to
// overwrite a stored reflection with an empty one. See
// assets/js/behistorical-beintheroom-capture.js for why.
(() => {
  'use strict';

  const scenario = window.BH_LIVE_ROOM;
  const app = document.getElementById('room-app');
  if (!scenario || !app) return;

  const storageKey = `behistorical-room-live-${scenario.id}`;
  const endingsKey = `${storageKey}-endings`;
  const fresh = () => ({ started: false, cursor: 0, choices: {}, docs: {}, replies: {}, reflection: '' });
  let state = load();

  function load() {
    try { return { ...fresh(), ...JSON.parse(localStorage.getItem(storageKey) || '{}') }; }
    catch { return fresh(); }
  }
  function save() {
    try { localStorage.setItem(storageKey, JSON.stringify(state)); }
    catch { /* Private browsing, or storage blocked: the page still plays. */ }
  }
  function foundEndings() {
    try { return JSON.parse(localStorage.getItem(endingsKey) || '[]'); }
    catch { return []; }
  }
  function rememberEnding(id) {
    const found = foundEndings();
    if (found.includes(id)) return;
    found.push(id);
    try { localStorage.setItem(endingsKey, JSON.stringify(found)); } catch { /* as above */ }
  }

  function esc(value) {
    return String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  }
  const lines = text => esc(text).replace(/\n/g, '<br>');

  // ── Conditions ──────────────────────────────────────────────────────────────
  // A `when` string is a list of terms separated by spaces, all of which must
  // hold. A term is a flag ("testimony"), a negated flag ("!women"), a gauge
  // test ("heat>=7", "coin<=1"), or alternatives joined by "|". An empty or
  // missing `when` always holds.
  function holds(when, run) {
    if (!when) return true;
    return when.trim().split(/\s+/).every(term => term.split('|').some(part => {
      const gauge = part.match(/^([a-z_]+)(>=|<=)(-?\d+)$/i);
      if (gauge) {
        const value = run.gauges[gauge[1]];
        return gauge[2] === '>=' ? value >= Number(gauge[3]) : value <= Number(gauge[3]);
      }
      return part.startsWith('!') ? !run.flags.has(part.slice(1)) : run.flags.has(part);
    }));
  }

  function apply(effects, gauges) {
    for (const [id, delta] of Object.entries(effects || {})) {
      gauges[id] = Math.max(0, Math.min(10, (gauges[id] ?? 0) + delta));
    }
  }

  // ── The timeline ────────────────────────────────────────────────────────────
  function buildTimeline() {
    const items = [];
    const run = { flags: new Set(), gauges: {} };
    scenario.gauges.forEach(gauge => { run.gauges[gauge.id] = gauge.start; });
    let blocked = false;

    // Returns false when the timeline has to stop at an unanswered item.
    function pushBeats(beats, prefix) {
      for (let index = 0; index < (beats || []).length; index++) {
        const beat = beats[index];
        if (!holds(beat.when, run)) continue;
        const key = `${prefix}-${index}`;
        if (beat.type === 'doc') {
          const answer = state.docs[beat.id];
          items.push({ kind: 'doc', key, beat, answer });
          if (answer === undefined) return false;
        } else if (beat.type === 'reply') {
          const answer = state.replies[beat.id];
          items.push({ kind: 'reply', key, beat, answer });
          if (!answer) return false;
        } else if (beat.type === 'event') {
          apply(beat.effects, run.gauges);
          items.push({ kind: 'narrate', key, beat, effects: beat.effects });
        } else {
          items.push({ kind: beat.type, key, beat });
        }
      }
      return true;
    }

    for (const scene of scenario.scenes) {
      items.push({ kind: 'scene', key: `scene-${scene.id}`, scene });
      if (!pushBeats(scene.beats, `${scene.id}-b`)) { blocked = true; break; }
      if (scene.choice) {
        const chosen = scene.choice.options.find(option => option.id === state.choices[scene.id]);
        items.push({ kind: 'choice', key: `choice-${scene.id}`, scene, chosen });
        if (!chosen) { blocked = true; break; }
        (chosen.flags || []).forEach(flag => run.flags.add(flag));
        apply(chosen.effects, run.gauges);
        if (!pushBeats(chosen.outcome, `${scene.id}-o`)) { blocked = true; break; }
        items.push({ kind: 'ledger', key: `ledger-${scene.id}`, effects: chosen.effects });
      }
      if (!pushBeats(scene.after, `${scene.id}-a`)) { blocked = true; break; }
    }

    let ending = null;
    if (!blocked) {
      ending = scenario.endings.find(candidate => holds(candidate.when, run));
      items.push({ kind: 'ending', key: 'ending', ending, run });
      items.push({ kind: 'record', key: 'record' });
      items.push({ kind: 'reflection', key: 'reflection', ending, run });
    }
    return { items, run, ending };
  }

  // What the gauges and tracker should show: only what the student has seen.
  function shownRun(items, count) {
    const run = { flags: new Set(), gauges: {} };
    scenario.gauges.forEach(gauge => { run.gauges[gauge.id] = gauge.start; });
    items.slice(0, count).forEach(item => {
      if (item.kind === 'choice' && item.chosen) (item.chosen.flags || []).forEach(flag => run.flags.add(flag));
      if (item.effects) apply(item.effects, run.gauges);
    });
    return run;
  }

  const castMember = id => scenario.cast.find(person => person.id === id) || { id, name: id, role: '', tone: 'steel' };
  const initials = name => name.replace(/^(Monsieur|Madame|The)\s+/i, '').split(/\s+/).map(word => word[0]).join('').slice(0, 2).toUpperCase();

  function effectChips(effects) {
    const chips = Object.entries(effects || {}).filter(([, delta]) => delta).map(([id, delta]) => {
      const gauge = scenario.gauges.find(candidate => candidate.id === id);
      const good = gauge && gauge.danger ? delta < 0 : delta > 0;
      return `<span class="live-chip ${good ? 'up' : 'down'}">${esc(gauge ? gauge.label : id)} ${delta > 0 ? '+' : '−'}${Math.abs(delta)}</span>`;
    });
    return chips.join('');
  }

  function trackerLists(run) {
    const pick = list => (list || []).filter(entry => holds(entry.when, run)).map(entry => entry.text);
    return { included: pick(scenario.tracker.included), excluded: pick(scenario.tracker.excluded) };
  }

  // ── Rendering one item ──────────────────────────────────────────────────────
  function renderItem(item) {
    const beat = item.beat;
    switch (item.kind) {
      case 'scene':
        return `<div class="live-scene"><span class="live-scene-kicker">${esc(item.scene.kicker)}</span><h2>${esc(item.scene.title)}</h2></div>`;
      case 'narrate':
        return `<p class="live-narrate">${lines(beat.text)}</p>${item.effects && effectChips(item.effects) ? `<div class="live-ledger">${effectChips(item.effects)}</div>` : ''}`;
      case 'say': {
        const person = castMember(beat.who);
        return `<div class="live-say tone-${esc(person.tone)}">
          <span class="live-avatar" aria-hidden="true">${esc(initials(person.name))}</span>
          <div class="live-bubble"><span class="live-speaker">${esc(person.name)}<span class="live-speaker-role">${person.role ? `, ${esc(person.role)}` : ''}</span></span><p>${lines(beat.text)}</p></div>
        </div>`;
      }
      case 'doc': {
        const answered = item.answer !== undefined;
        const options = beat.ask.options.map((option, index) => {
          const picked = answered && item.answer === index;
          const mark = answered && option.right ? ' is-right' : '';
          return `<button class="live-option${mark}" type="button" data-doc="${esc(beat.id)}" data-index="${index}" aria-pressed="${picked}"${answered ? ' disabled' : ''}>${esc(option.text)}</button>`;
        }).join('');
        const reply = answered ? `<p class="live-doc-reply">${lines(beat.ask.options[item.answer].reply)}</p>` : '';
        return `<figure class="live-doc">
          <figcaption><span class="live-doc-label">A document</span><strong>${esc(beat.title)}</strong><span class="live-doc-meta">${esc(beat.meta)}</span></figcaption>
          <blockquote>${lines(beat.text)}</blockquote>
        </figure>
        <div class="live-ask"><p class="live-ask-prompt">${lines(beat.ask.prompt)}</p><div class="live-options" role="group" aria-label="What the document claims">${options}</div>${reply}</div>`;
      }
      case 'reply': {
        const person = castMember(beat.who);
        const said = `<div class="live-say tone-${esc(person.tone)}"><span class="live-avatar" aria-hidden="true">${esc(initials(person.name))}</span>
          <div class="live-bubble"><span class="live-speaker">${esc(person.name)}<span class="live-speaker-role">${person.role ? `, ${esc(person.role)}` : ''}</span></span><p>${lines(beat.prompt)}</p></div></div>`;
        if (item.answer) return `${said}<div class="live-say live-you"><div class="live-bubble"><span class="live-speaker">You</span><p>${lines(item.answer)}</p></div></div>`;
        return `${said}<div class="live-reply">
          <label for="reply-${esc(beat.id)}">${esc(beat.label)}</label>
          <textarea id="reply-${esc(beat.id)}" rows="3" placeholder="${esc(beat.placeholder || '')}"></textarea>
          <div class="live-reply-row"><button class="live-button" type="button" data-reply="${esc(beat.id)}">Say it</button><span class="live-hint" id="reply-hint-${esc(beat.id)}" role="status"></span></div>
        </div>`;
      }
      case 'choice': {
        const options = item.scene.choice.options.map(option => {
          const picked = item.chosen && item.chosen.id === option.id;
          return `<button class="live-option live-decision" type="button" data-choice="${esc(item.scene.id)}" data-option="${esc(option.id)}" aria-pressed="${Boolean(picked)}"${item.chosen ? ' disabled' : ''}>${esc(option.label)}</button>`;
        }).join('');
        return `<div class="live-choice${item.chosen ? ' is-made' : ''}">
          <p class="live-choice-prompt"><span class="live-choice-label">${item.chosen ? 'You chose' : 'Your move'}</span>${esc(item.scene.choice.prompt)}</p>
          <div class="live-options" role="group" aria-label="${esc(item.scene.choice.prompt)}">${options}</div>
          ${item.chosen ? '' : '<p class="live-hint">You cannot take it back.</p>'}
        </div>`;
      }
      case 'ledger': {
        const chips = effectChips(item.effects);
        return chips ? `<div class="live-ledger"><span class="live-ledger-label">In your shop</span>${chips}</div>` : '<div class="live-ledger"><span class="live-ledger-label">In your shop</span><span class="live-chip">Nothing you can count, yet</span></div>';
      }
      case 'ending': {
        const lists = trackerLists(item.run);
        const found = foundEndings().length;
        const own = Object.values(state.replies)[0];
        return `<section class="live-ending">
          <span class="live-scene-kicker">How it ended for you</span>
          <h2>${esc(item.ending.title)}</h2>
          <p>${lines(item.ending.text)}</p>
          <div class="live-tracker-final">
            <div><h3>${esc(scenario.tracker.label)}</h3><ul>${lists.included.map(text => `<li>${esc(text)}</li>`).join('') || '<li>No one yet</li>'}</ul></div>
            <div><h3>Who it left out</h3><ul>${lists.excluded.map(text => `<li>${esc(text)}</li>`).join('') || '<li>No one you were asked about</li>'}</ul></div>
          </div>
          ${own ? `<p class="live-echo">Last winter you told Luc: <q>${esc(own)}</q></p>` : ''}
          <p class="live-found">Endings found on this device: ${found} of ${scenario.endings.length}</p>
        </section>`;
      }
      case 'record':
        return `<section class="live-record">
          <span class="live-scene-kicker">The real record</span>
          <h2>${esc(scenario.record.title)}</h2>
          <p>${lines(scenario.record.intro)}</p>
          <ol>${scenario.record.items.map(entry => `<li><span class="live-year">${esc(entry.year)}</span><span>${lines(entry.text)}</span></li>`).join('')}</ol>
          <p class="live-record-close">${lines(scenario.record.close)}</p>
        </section>`;
      case 'reflection':
        return `<section class="live-reflection">
          <span class="live-scene-kicker">Step out of the room</span>
          <h2>Your verdict</h2>
          <label for="room-reflection">${lines(scenario.reflection.prompt)}</label>
          <textarea id="room-reflection" rows="8" placeholder="${esc(scenario.reflection.placeholder || '')}">${esc(state.reflection)}</textarea>
          <p class="live-hint" id="room-reflection-status" role="status">This box saves as you type and is what reaches Canvas through Gather All My Work on the lesson page.</p>
          <div class="live-actions">
            <button class="live-button" type="button" id="live-copy">Copy my run for Socrates</button>
            <a class="live-button ghost" id="live-open-coach" href="${esc(coachUrl())}" target="_blank" rel="noopener">Open MagicSchool</a>
            <button class="live-button ghost" type="button" id="live-replay">Play again, choose differently</button>
          </div>
          <p class="live-hint" id="live-copy-status" role="status" aria-live="polite"></p>
          <pre class="live-paste" id="live-paste" tabindex="0" hidden></pre>
          <details class="live-teaching">
            <summary>What this room was teaching</summary>
            <p><strong>Thematic focus:</strong> ${esc(scenario.alignment.theme)}</p>
            ${scenario.alignment.objectives.map(text => `<p><strong>Learning objective:</strong> ${esc(text)}</p>`).join('')}
            <p><strong>Reasoning process:</strong> ${esc(scenario.alignment.reasoning)}</p>
            <p><strong>Skill:</strong> ${esc(scenario.alignment.skill)}</p>
            ${scenario.alignment.keyConcepts.map(kc => `<p><strong>${esc(kc.code)}:</strong> ${esc(kc.text)}</p>`).join('')}
            <p>${esc(scenario.disclosure)}</p>
            <ul>${scenario.sources.map(source => `<li><a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.label)}</a></li>`).join('')}</ul>
          </details>
        </section>`;
      default:
        return '';
    }
  }

  // An item's node is rebuilt only when what it shows has changed, so the feed
  // grows by appending and a screen reader hears the new beat, not the page.
  function signature(item) {
    if (item.kind === 'doc' || item.kind === 'reply') return `${item.key}:${item.answer ?? ''}`;
    if (item.kind === 'choice') return `${item.key}:${item.chosen ? item.chosen.id : ''}`;
    if (item.kind === 'ending') return `${item.key}:${item.ending.id}:${foundEndings().length}`;
    return item.key;
  }

  const DEFAULT_MAGICSCHOOL_URL = 'https://student.magicschool.ai/s/login?joinCode=czwb9Q';
  function coachUrl() {
    return window.BHClassroom ? window.BHClassroom.resolveMagicSchoolUrl(DEFAULT_MAGICSCHOOL_URL) : DEFAULT_MAGICSCHOOL_URL;
  }

  // ── The page ────────────────────────────────────────────────────────────────
  function shell() {
    const title = esc(scenario.title).replace(/\*([^*]+)\*/g, '<em>$1</em>');
    app.innerHTML = `
      <nav class="live-topbar">
        <span class="live-brand">BeInTheRoom</span>
        <a class="live-back" href="${esc(scenario.lessonUrl)}">← Topic ${esc(scenario.id)}</a>
      </nav>
      <div class="live-hud" id="live-hud" hidden>
        <div class="live-gauges" id="live-gauges"></div>
        <div class="live-tracker" id="live-tracker"></div>
      </div>
      <header class="live-cover" id="live-cover">
        <div class="live-cover-inner">
          <div class="live-scene-kicker">${esc(scenario.location)} · ${esc(scenario.date)}</div>
          <h1>${title}</h1>
          ${scenario.opening.lines.map(text => `<p class="live-cover-line">${lines(text)}</p>`).join('')}
          <div class="live-brief">
            <h2>Your brief</h2>
            <p><strong>Who you are.</strong> ${esc(scenario.opening.brief.who)}</p>
            <p><strong>What you want.</strong> ${esc(scenario.opening.brief.want)}</p>
            <p><strong>What you cannot lose.</strong> ${esc(scenario.opening.brief.fear)}</p>
            <ul class="live-brief-gauges">${scenario.gauges.map(gauge => `<li><strong>${esc(gauge.label)}:</strong> ${esc(gauge.hint)}</li>`).join('')}</ul>
            <p class="live-brief-rule">${esc(scenario.opening.brief.rule)}</p>
          </div>
          <button class="live-button big" type="button" id="live-start">${esc(scenario.opening.start)}</button>
        </div>
      </header>
      <main class="live-main" id="live-main" hidden>
        <div class="live-feed" id="live-feed" aria-live="polite"></div>
        <div class="live-continue" id="live-continue-wrap"><button class="live-button big" type="button" id="live-continue">Continue</button></div>
      </main>`;
  }

  let lastGauges = null;
  function renderHud(run) {
    const gauges = document.getElementById('live-gauges');
    gauges.innerHTML = scenario.gauges.map(gauge => {
      const value = run.gauges[gauge.id];
      const moved = lastGauges && lastGauges[gauge.id] !== value;
      return `<div class="live-gauge${gauge.danger ? ' danger' : ''}${moved ? ' moved' : ''}" title="${esc(gauge.hint)}">
        <span class="live-gauge-label">${esc(gauge.label)}</span>
        <span class="live-gauge-bar" role="img" aria-label="${esc(gauge.label)}: ${value} out of 10"><span style="width:${value * 10}%"></span></span>
        <span class="live-gauge-value" aria-hidden="true">${value}</span>
      </div>`;
    }).join('');
    lastGauges = { ...run.gauges };
    const lists = trackerLists(run);
    const tracker = document.getElementById('live-tracker');
    tracker.innerHTML = lists.included.length || lists.excluded.length
      ? `<span class="live-tracker-label">${esc(scenario.tracker.label)}:</span> ${lists.included.map(text => `<span class="live-tag in">${esc(text)}</span>`).join('')}${lists.excluded.map(text => `<span class="live-tag out">Left out: ${esc(text)}</span>`).join('')}`
      : `<span class="live-tracker-label">${esc(scenario.tracker.label)}:</span> <span class="live-tag">Not decided yet</span>`;
  }

  function sync(focusNew) {
    const started = state.started;
    document.getElementById('live-cover').hidden = started;
    document.getElementById('live-main').hidden = !started;
    document.getElementById('live-hud').hidden = !started;
    if (!started) return;

    const { items, ending } = buildTimeline();
    if (state.cursor < 1) state.cursor = 1;
    if (state.cursor > items.length) state.cursor = items.length;
    const visible = items.slice(0, state.cursor);
    if (ending && visible.some(item => item.kind === 'ending')) rememberEnding(ending.id);

    const feed = document.getElementById('live-feed');
    const nodes = Array.from(feed.children);
    // Anything on screen that is no longer in the timeline (a replay) goes.
    nodes.slice(visible.length).forEach(node => node.remove());
    let newest = null;
    visible.forEach((item, index) => {
      const sig = signature(item);
      let node = feed.children[index];
      if (node && node.dataset.sig === sig) return;
      const next = document.createElement('div');
      next.className = `live-item live-item-${item.kind}`;
      next.dataset.sig = sig;
      next.innerHTML = renderItem(item);
      if (node) node.replaceWith(next);
      else { feed.appendChild(next); newest = next; }
    });

    renderHud(shownRun(items, state.cursor));

    const last = visible[visible.length - 1];
    const waiting = last && ((last.kind === 'doc' && last.answer === undefined) || (last.kind === 'reply' && !last.answer) || (last.kind === 'choice' && !last.chosen));
    const atEnd = state.cursor >= items.length;
    document.getElementById('live-continue-wrap').hidden = waiting || atEnd;
    save();

    if (focusNew && newest) {
      newest.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'center' });
    }
  }

  function advance() {
    state.cursor += 1;
    sync(true);
  }

  // ── The Socrates paste ──────────────────────────────────────────────────────
  // Socrates stays Socrates here: the paste hands him the run and the
  // reflection and asks for the persona's own bounded help. Its last line is
  // byte-identical to the one a checkpoint and every other scenario sends.
  function buildPaste() {
    const { run, ending } = buildTimeline();
    const decisions = scenario.scenes.filter(scene => scene.choice).map(scene => {
      const chosen = scene.choice.options.find(option => option.id === state.choices[scene.id]);
      return `- ${scene.title}: ${chosen ? chosen.label : 'not decided'}`;
    });
    const lists = trackerLists(run);
    const own = Object.values(state.replies)[0] || '';
    return `Socrates, I just finished a BeInTheRoom simulation. I played a role and made decisions, and now I am stepping out of character.\n\nScenario: ${scenario.title.replaceAll('*', '')}\nTopic: ${scenario.id}, ${scenario.topicTitle}\nWhere and when: ${scenario.location}, ${scenario.date}\nMy role: ${scenario.opening.brief.who}\n\nMy decisions:\n${decisions.join('\n')}\n\n${scenario.tracker.label}: ${lists.included.join('; ') || 'no one'}\nWho it left out: ${lists.excluded.join('; ') || 'no one I was asked about'}\nHow it ended: ${ending ? `${ending.title}. ${ending.text}` : 'I have not finished yet.'}\n${own ? `\nWhat I said in character: ${own}\n` : ''}\nThe reflection question: ${scenario.reflection.prompt}\n\nMy reflection:\n${state.reflection.trim() || '(I have not written it yet.)'}\n\nCoach me on one thing: does my reflection explain one change and one continuity, each with evidence? Name the weakest part and tell me what to revise. After I revise once, tell me whether it holds. The reflection box at the end of the scenario is what reaches Canvas through Gather All My Work on the lesson page.\n\nGive me one thing to work on at a time. Do not write my final answer for me.`;
  }

  async function copyPaste() {
    const status = document.getElementById('live-copy-status');
    const box = document.getElementById('live-paste');
    if (!state.reflection.trim()) {
      status.textContent = 'Write your verdict first. Socrates needs something to push on.';
      document.getElementById('room-reflection').focus();
      return;
    }
    const paste = buildPaste();
    box.textContent = paste;
    box.hidden = false;
    try {
      await navigator.clipboard.writeText(paste);
      status.textContent = 'Copied. Open MagicSchool and paste it to Socrates.';
    } catch {
      const range = document.createRange();
      range.selectNodeContents(box);
      const selection = window.getSelection();
      selection.removeAllRanges();
      selection.addRange(range);
      status.textContent = 'Copying was blocked, so the text is selected below. Copy it yourself, then paste it to Socrates.';
    }
  }

  // ── Events ──────────────────────────────────────────────────────────────────
  app.addEventListener('click', event => {
    const target = event.target.closest('button');
    if (!target) return;
    if (target.id === 'live-start') {
      state.started = true;
      state.cursor = Math.max(state.cursor, 2);
      sync(true);
      document.getElementById('live-continue').focus();
    } else if (target.id === 'live-continue') {
      advance();
    } else if (target.dataset.doc) {
      if (state.docs[target.dataset.doc] !== undefined) return;
      state.docs[target.dataset.doc] = Number(target.dataset.index);
      sync(false);
      document.getElementById('live-continue').focus();
    } else if (target.dataset.choice) {
      if (state.choices[target.dataset.choice]) return;
      state.choices[target.dataset.choice] = target.dataset.option;
      advance();
      document.getElementById('live-continue').focus();
    } else if (target.dataset.reply) {
      const box = document.getElementById(`reply-${target.dataset.reply}`);
      const text = box.value.trim();
      if (text.length < 15) {
        document.getElementById(`reply-hint-${target.dataset.reply}`).textContent = 'Give a real answer, at least a full sentence.';
        box.focus();
        return;
      }
      state.replies[target.dataset.reply] = text;
      advance();
      document.getElementById('live-continue').focus();
    } else if (target.id === 'live-copy') {
      copyPaste();
    } else if (target.id === 'live-replay') {
      // The reflection is deliberately kept: a replay is a second run at the
      // history, not a reason to lose the writing.
      state = { ...fresh(), started: true, cursor: 2, reflection: state.reflection };
      lastGauges = null;
      document.getElementById('live-feed').innerHTML = '';
      sync(false);
      window.scrollTo({ top: 0 });
      document.getElementById('live-continue').focus();
    }
  });

  app.addEventListener('input', event => {
    if (event.target.id !== 'room-reflection') return;
    state.reflection = event.target.value;
    save();
    if (window.BHBeInTheRoomCapture) {
      window.BHBeInTheRoomCapture.save(scenario.id, scenario.reflection.prompt, state.reflection);
    }
  });

  // A stored reflection with no page state behind it (a cleared page key, a
  // second device visit) is put back in the box. Read only: nothing is written
  // to the capture key here.
  if (!state.reflection.trim() && window.BHBeInTheRoomCapture) {
    const saved = window.BHBeInTheRoomCapture.read(scenario.id);
    if (saved && saved.a) state.reflection = saved.a;
  }

  shell();
  sync(false);
})();
